// Bounded research probe for candidate vendor sources (not part of the Worker).
// One GET per candidate URL, 8 s timeout, 400 KB cap, no retries, no bypassing.
import { writeFile } from 'node:fs/promises';

const CANDIDATES = [
  ['freshmarket.co.il', 'https://www.freshmarket.co.il/robots.txt'],
  ['freshmarket.co.il', 'https://www.freshmarket.co.il/catalogsearch/result/?q=lavazza'],
  ['victoryonline.co.il', 'https://www.victoryonline.co.il/robots.txt'],
  ['yohananof.co.il', 'https://www.yohananof.co.il/robots.txt'],
  ['mega.co.il', 'https://www.mega.co.il/robots.txt'],
  ['carrefour.co.il', 'https://www.carrefour.co.il/robots.txt'],
  ['coffeeshop.co.il', 'https://www.coffeeshop.co.il/robots.txt'],
  ['coffeetime.co.il', 'https://www.coffeetime.co.il/robots.txt'],
  ['ilcafe.co.il', 'https://www.ilcafe.co.il/robots.txt'],
  ['coffeeitalia.co.uk', 'https://www.coffeeitalia.co.uk/robots.txt'],
  ['espres.so', 'https://www.espres.so/robots.txt'],
  ['coffeedesk.com', 'https://www.coffeedesk.com/robots.txt'],
  ['roastmarket.com', 'https://www.roastmarket.com/robots.txt'],
  ['kaffeekontor.de', 'https://www.kaffeekontor.de/robots.txt'],
  ['coffeehen.co.il', 'https://www.coffeehen.co.il/robots.txt']
];

const CAP = 400 * 1024;
async function get(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: controller.signal,
      headers: {
        'user-agent': 'attention-shoppers-happy-hunting/0.1 (local research probe; contact: repo owner)',
        accept: 'text/html,application/xhtml+xml,text/plain;q=0.9,*/*;q=0.5'
      }
    });
    const reader = res.body?.getReader();
    const chunks = [];
    let size = 0;
    if (reader) {
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value);
        size += value.length;
        if (size > CAP) { await reader.cancel(); break; }
      }
    }
    const text = Buffer.concat(chunks.map(c => Buffer.from(c))).toString('utf8');
    return { status: res.status, url: res.url, contentType: res.headers.get('content-type'), bytes: size, text };
  } catch (error) {
    return { status: 0, error: error?.name === 'AbortError' ? 'timeout' : (error?.message ?? String(error)), text: '' };
  } finally {
    clearTimeout(timer);
  }
}

const results = [];
for (const [domain, url] of CANDIDATES) {
  const res = await get(url);
  const evidence = {
    domain, url, status: res.status, finalUrl: res.url ?? null, contentType: res.contentType ?? null,
    bytes: res.bytes ?? 0, error: res.error ?? null,
    title: (res.text.match(/<title[^>]*>([\s\S]{0,200}?)<\/title>/i)?.[1] ?? '').trim() || null,
    hasLavazza: /lavazza/i.test(res.text),
    hasCremaGusto: /crema\s*e\s*gusto/i.test(res.text),
    signup: /shopify|woocommerce|magento|wix|pepyaka|salla|zu\b|angular/i.test(res.text),
    robotsSnippet: res.url?.endsWith('robots.txt') ? res.text.slice(0, 300).replace(/\s+/g, ' ') : null,
    snippet: res.text.slice(0, 160).replace(/\s+/g, ' ')
  };
  results.push(evidence);
  console.log(JSON.stringify(evidence));
}
await writeFile('/tmp/probe-results.json', JSON.stringify(results, null, 2));
