// Pucks (pucks.co.il), Ramla, Israel — Lavazza ground coffee in a vacuum brick:
// Crema e Gusto Classico 250 g and Qualità Oro 250 g.
// Source of truth: schema.org Product JSON-LD on the public product page.
// Price and listed availability are observed. Shipping is only calculated at
// checkout, so it stays unknown and the offer cannot win the ranking.

import { classifyListing } from '../catalog.js';
import { findJsonLd, textOf } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://pucks.co.il/product/lavazza-crema-e-gusto-ground-coffee-250g';
const QUALITA_ORO_URL = 'https://pucks.co.il/product/lavazza-qualita-oro-ground-coffee-250gr';

const AVAILABILITY = {
  'https://schema.org/InStock': 'in_stock',
  'https://schema.org/LimitedAvailability': 'in_stock',
  'https://schema.org/OutOfStock': 'out_of_stock',
  'https://schema.org/SoldOut': 'out_of_stock'
};

export const pucks = {
  id: 'pucks',
  name: 'Pucks (פאקס)',
  homepage: 'https://pucks.co.il',
  allowedHosts: ['pucks.co.il', 'www.pucks.co.il'],
  parserVersion: 'pucks/2',
  offers: [
    { id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery', productId: 'lavazza-crema-e-gusto-vacuum-ground' },
    { id: 'qualita-oro-250g', url: QUALITA_ORO_URL, kind: 'delivery', productId: 'lavazza-qualita-oro-vacuum-ground' }
  ],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        observations.push(parsePucksProduct(response.text, { now, url: offer.url, productId: offer.productId ?? null }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parsePucksProduct(html, { now, url = PRODUCT_URL, productId = null } = {}) {
  const product = findJsonLd(html, 'Product');
  if (!product) throw parseError('No schema.org Product JSON-LD found', { url });
  const offer = product.offers ?? {};
  const name = String(product.name ?? '');
  const classification = classifyListing(name, { productId });
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }
  const priceAmount = Number(offer.price);
  if (!Number.isFinite(priceAmount)) throw parseError('Price missing from JSON-LD offer', { name, price: offer.price });
  const currency = String(offer.priceCurrency ?? '').toUpperCase();
  if (!currency) throw parseError('Currency missing from JSON-LD offer', { name });
  const availability = AVAILABILITY[String(offer.availability ?? '')] ?? 'unknown';

  const shippingNote = /המשלוח מחושב/.test(html)
    ? 'Shipping is calculated at checkout'
    : 'Shipping terms are not published on the product page';

  return createObservation({
    vendor: pucks,
    itemUrl: url,
    product: {
      productId: classification.productId,
      name,
      sku: product.sku ?? product.mpn ?? null,
      gtin: product.gtin13 ?? product.gtin ?? null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: product.category ?? null
    },
    price: { amount: priceAmount, currency },
    availability,
    availabilityEvidence: {
      url,
      value: String(offer.availability ?? 'not stated'),
      note: 'Availability comes from the product page structured data, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      certainty: 'unknown',
      amount: null,
      destination: { scope: 'country', country: 'IL' },
      note: shippingNote,
      evidence: { url, retrievedAt: null, note: 'Store states shipping is calculated at checkout.' }
    },
    now
  });
}

export function pucksProductText(html) {
  return textOf(html).slice(0, 400);
}

// Recorded vendor pages and the URL → fixture routing used by the offline tools.
//
// One source of truth for `npm run check:sources -- --fixture`,
// `npm run cron:offline`, the browser QA fixture server and the unit tests, so a
// new tracked offer cannot silently lose its fixture. Every fixture is a
// minimized excerpt of a real public product page (see docs/SOURCES.md).

import { readFile } from 'node:fs/promises';
import { registeredVendors } from '../../src/vendors/index.js';

/** fixture file per "<vendorId>:<offerId>". */
export const FIXTURE_BY_OFFER = {
  'coffeeman:classico-250g': 'coffeeman-product.windows-1255.html',
  'coffeeman:classico-1000g-4pack': 'coffeeman-4pack-product.windows-1255.html',
  'coffeeman:classico-2000g-8pack': 'coffeeman-8pack-product.windows-1255.html',
  'coffeeman:qualita-oro-250g': 'coffeeman-qualita-oro-product.windows-1255.html',
  'coffeeman:qualita-oro-1000g-4pack': 'coffeeman-qualita-oro-4pack-product.windows-1255.html',
  'coffeeman:qualita-oro-2000g-8pack': 'coffeeman-qualita-oro-8pack-product.windows-1255.html',
  'pucks:classico-250g': 'pucks-product.html',
  'pucks:qualita-oro-250g': 'pucks-qualita-oro-product.html',
  'coffee4u:crema-e-gusto-250g-ground': 'coffee4u-product.windows-1255.html'
};

const WINDOWS_1255 = 'text/html; charset=windows-1255';
const CONTENT_TYPE_BY_FILE = {
  'coffeeman-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-4pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-8pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-oro-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-oro-4pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-qualita-oro-8pack-product.windows-1255.html': WINDOWS_1255,
  'coffeeman-product.outofstock.windows-1255.html': WINDOWS_1255,
  'pucks-product.html': 'text/html; charset=utf-8',
  'pucks-product.outofstock.html': 'text/html; charset=utf-8',
  'pucks-product.preorder.html': 'text/html; charset=utf-8',
  'pucks-qualita-oro-product.html': 'text/html; charset=utf-8',
  'coffee4u-product.windows-1255.html': WINDOWS_1255,
  'coffee4u-product.outofstock.windows-1255.html': WINDOWS_1255
};

export const FIXTURES_DIR = new URL('./', import.meta.url);

/** Every tracked offer together with the fixture that reproduces its page. */
export function trackedOffers() {
  const offers = [];
  for (const vendor of registeredVendors()) {
    for (const offer of vendor.offers ?? []) {
      const file = FIXTURE_BY_OFFER[`${vendor.id}:${offer.id}`] ?? null;
      offers.push({ vendorId: vendor.id, offerId: offer.id, url: offer.url, productId: offer.productId ?? null, file });
    }
  }
  return offers;
}

const urlToOffer = new Map(trackedOffers().map(offer => [offer.url, offer]));

/** Read a recorded fixture by file name. */
export async function readFixture(file) {
  const bytes = await readFile(new URL(file, FIXTURES_DIR));
  const contentType = CONTENT_TYPE_BY_FILE[file] ?? 'text/html; charset=utf-8';
  return { file, bytes, contentType, text: new TextDecoder('utf-8', { fatal: false }).decode(bytes) };
}

/** Read the fixture that corresponds to a tracked vendor URL, or null. */
export async function readFixtureForUrl(url) {
  const offer = urlToOffer.get(String(url));
  if (!offer?.file) return null;
  return { ...(await readFixture(offer.file)), offer };
}

/** Fixture fetch for the production bounded fetcher shape (returns a Response). */
export function createFixtureFetch() {
  return async (url, init = {}) => {
    const hit = await readFixtureForUrl(url);
    if (!hit) return new Response('no fixture for this URL', { status: 404 });
    void init;
    return new Response(hit.bytes, { status: 200, headers: { 'content-type': hit.contentType } });
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { decodeBuffer, decodeEntities, decodeHtml } from '../src/lib/text.js';
import { parseCoffeemanProduct, parseShippingOptions } from '../src/vendors/coffeeman.js';
import { parsePucksProduct } from '../src/vendors/pucks.js';
import { parseCoffee4uProduct, parseCoffee4uShipping } from '../src/vendors/coffee4u.js';
