// Text, charset and HTML helpers shared by deterministic vendor adapters.
// Fetched pages are untrusted data. We only extract values with narrow patterns.

const WINDOWS_1255 = 'windows-1255';

export function decodeBuffer(bytes, charset) {
  const encodings = [];
  if (charset) encodings.push(charset.toLowerCase());
  encodings.push(WINDOWS_1255, 'utf-8');
  for (const encoding of encodings) {
    try {
      return new TextDecoder(encoding, { fatal: false }).decode(bytes);
    } catch {
      // Try the next candidate.
    }
  }
  return new TextDecoder('utf-8', { fatal: false }).decode(bytes);
}

/** Detect the declared charset from a meta tag, defaulting to UTF-8. */
export function declaredCharset(html) {
  const probe = html.slice(0, 4096).toLowerCase();
  const meta = /charset=["']?\s*([a-z0-9_-]+)/i.exec(probe);
  return meta ? meta[1] : 'utf-8';
}

export function decodeHtml(bytes, htmlHint = '') {
  const hint = declaredCharset(htmlHint || decodeBuffer(bytes, 'utf-8'));
  return decodeBuffer(bytes, hint);
}

/**
 * Decode HTML entities in extracted text. Vendor titles publish names such as
 * "Lavazza Qualit&#224; Oro", and an undecoded entity would hide the line name.
 * Only entities are decoded here; fetched markup is still never treated as
 * instructions and never rendered as HTML.
 */
export function decodeEntities(text) {
  if (text == null) return '';
  const NAMED = {
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', shy: '', hellip: '…', ndash: '–', mdash: '—',
    agrave: 'à', aacute: 'á', auml: 'ä', egrave: 'è', eacute: 'é', igrave: 'ì', ograve: 'ò', oacute: 'ó', ugrave: 'ù', ccedil: 'ç',
    Agrave: 'À', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü'
  };
  return String(text).replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);/g, (match, entity) => {
    if (entity.startsWith('#')) {
      const hex = entity[1] === 'x' || entity[1] === 'X';
      const code = Number.parseInt(entity.slice(hex ? 2 : 1), hex ? 16 : 10);
      if (!Number.isFinite(code) || code <= 0 || code > 0x10ffff) return match;
      try {
        return String.fromCodePoint(code);
      } catch {
        return match;
      }
    }
    return Object.prototype.hasOwnProperty.call(NAMED, entity) ? NAMED[entity] : match;
  });
}

export function stripTags(html) {
  return html.replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
}

export function collapse(text) {
  return text.replace(/\s+/g, ' ').trim();
}

export function textOf(html) {
  return collapse(stripTags(html));
}

export function firstMatch(text, pattern) {
  const match = pattern.exec(text);
  return match ? match[1] : null;
}

/** Parse a decimal number from a price-like string, tolerating thousands separators. */
export function parseDecimal(value) {
  if (value == null) return null;
  const cleaned = String(value).replace(/[^\d.,-]/g, '').replace(/,(?=\d{3}\b)/g, '');
  if (!/\d/.test(cleaned)) return null;
  const parsed = Number(cleaned.replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
}

/** Extract product/offer JSON from an application/ld+json script block. */
export function jsonLdBlocks(html) {
  const blocks = [];
  const pattern = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let match;
  while ((match = pattern.exec(html)) !== null) {
    try {
      blocks.push(JSON.parse(match[1]));
    } catch {
      blocks.push(null);
    }
  }
  return blocks;
}

export function findJsonLd(html, type) {
  for (const block of jsonLdBlocks(html)) {
    const items = Array.isArray(block) ? block : [block];
    for (const item of items) {
      if (item && item['@type'] === type) return item;
    }
  }
  return null;
}

// The local cron simulation must be repeatable: it is the command the handoff
// notes and the agent loop use to prove the scheduled pipeline still works.
// A fixture run must never be silently skipped because a previous run left a
// six-hour backoff window behind, and it must never consume the live run's
// state file either.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const run = promisify(execFile);
const script = fileURLToPath(new URL('../scripts/simulate-cron.mjs', import.meta.url));

async function simulate(cwd) {
  const { stdout, stderr } = await run(process.execPath, [script, '--offline'], {
    cwd,
    env: { ...process.env, BOARD_STATE_PATH: '' },
    timeout: 60_000
  });
  return { report: JSON.parse(stdout), stderr };
}

test('cron:offline simulation runs the full fixture pipeline twice in a row', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'cron-simulation-'));
  try {
    const first = await simulate(dir);
    const second = await simulate(dir);

    for (const [label, { report }] of [['first', first], ['second', second]]) {
      assert.equal(report.mode, 'offline fixtures', `${label} run mode`);
      assert.equal(report.summary.requests, 10, `${label} run stays inside the request budget`);
      assert.deepEqual(
        report.summary.vendors.map(vendor => [vendor.vendorId, vendor.saved, vendor.skipped ?? false]),
        [['coffeeman', 6, false], ['pucks', 2, false], ['coffee4u', 1, false]],
        `${label} run refreshes every vendor`
      );
      assert.equal(report.offers.length, 9, `${label} run persists all nine tracked offers`);
      assert.ok(report.offers.every(offer => offer.observedAt === report.summary.startedAt), `${label} run observations are fresh`);
      assert.ok(report.fx?.usd?.rate > 0, `${label} run records an FX reference rate`);
    }

    // The fixture run keeps its own state file so it can never consume the live
    // run's backoff window, and the state really is persisted between runs.
    const state = JSON.parse(await readFile(join(dir, '.shurik-local', 'board-offline.json'), 'utf8'));
    assert.equal(state.observations.length, 9);
    assert.equal(Object.keys(state.vendors).length, 3);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});
