// Build minimized test fixtures from the live pages retrieved during this iteration.
// CoffeeMan pages are windows-1255 single-byte documents, so the raw bytes are sliced
// through a latin1 view (one char per byte) to keep the declared charset honest.
import { writeFile } from 'node:fs/promises';

const UA = {
  'user-agent': 'attention-shoppers-happy-hunting/0.1 (local research probe; robots respected)',
  accept: 'text/html,*/*;q=0.8'
};
async function getBuffer(url) {
  const c = new AbortController();
  const t = setTimeout(() => c.abort(), 12000);
  try {
    const r = await fetch(url, { redirect: 'follow', signal: c.signal, headers: UA });
    return { status: r.status, buf: Buffer.from(await r.arrayBuffer()) };
  } finally {
    clearTimeout(t);
  }
}
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

const DIR = new URL('../tests/fixtures/', import.meta.url);

// --- CoffeeMan Qualità Rossa 250 g (windows-1255) ---------------------------
await sleep(8000); // honour the published Crawl-delay: 7 between requests
const cmUrl = 'https://www.coffeeman.co.il/product/250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-qualita-rossa';
const cm = await getBuffer(cmUrl);
if (cm.status !== 200) throw new Error(`coffeeman fetch failed: ${cm.status}`);
const latin = cm.buf.toString('latin1');
const h1Start = latin.indexOf('<h1');
const h1End = latin.indexOf('</h1>', h1Start) + '</h1>'.length;
const h1 = latin.slice(h1Start, h1End);
const markers = ['itemprop="price"', 'itemprop="priceCurrency"', 'itemprop="availability"', 'itemprop="sku"'];
const positions = markers.map(marker => latin.indexOf(marker));
if (positions.some(index => index < 0)) throw new Error(`coffeeman markers missing: ${JSON.stringify(positions)}`);
const offerFrom = Math.max(0, Math.min(...positions) - 700);
const offerTo = Math.max(...positions) + 900;
const offer = latin.slice(offerFrom, offerTo);
const deliveryStart = latin.indexOf('delivery-price-product');
if (deliveryStart < 0) throw new Error('coffeeman delivery block missing');
const delivery = latin.slice(deliveryStart, deliveryStart + 2600);
const cmFixture = [
  '<!DOCTYPE html><html><head>',
  '<meta http-equiv="Content-Type" content="text/html; charset=windows-1255" />',
  '<title>fixture: coffeeman qualita rossa product page excerpt</title>',
  '</head><body>',
  h1,
  offer,
  delivery,
  '</body></html>'
].join('');
await writeFile(new URL('coffeeman-qualita-rossa-product.windows-1255.html', DIR), Buffer.from(cmFixture, 'latin1'));
console.log('wrote coffeeman-qualita-rossa-product.windows-1255.html', cmFixture.length, 'chars',
  'priceAt', latin.slice(positions[0], positions[0] + 60).replace(/\s+/g, ' '));

// --- Pucks Qualità Rossa (utf-8 JSON-LD) ------------------------------------
function pucksFixture(html, label) {
  const scripts = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
  const product = scripts.map(match => match[1]).find(body => body.includes('"@type":"Product"'));
  if (!product) throw new Error(`${label}: no Product JSON-LD`);
  const note = /<p class="slide_cart__tax-note">[^<]*<\/p>/.exec(html)?.[0] ?? '';
  return [
    '<!DOCTYPE html>',
    '<html lang="he" dir="rtl">',
    '<head>',
    '<meta charset="utf-8">',
    `<title>fixture: pucks qualita rossa ${label} product page excerpt</title>`,
    '<script type="application/ld+json">',
    product,
    '</script>',
    '</head>',
    '<body>',
    note,
    '</body>',
    '</html>'
  ].join('\n');
}

const pucksPages = [
  ['lavazza-qualita-rossa-ground-coffee-250g', 'pucks-qualita-rossa-product.html'],
  ['lavazza-qualita-rossa-ground-coffee-powder-250g', 'pucks-qualita-rossa-outofstock-product.html']
];
for (const [slug, file] of pucksPages) {
  const url = `https://pucks.co.il/product/${slug}`;
  const res = await getBuffer(url);
  if (res.status !== 200) throw new Error(`pucks fetch failed ${url}: ${res.status}`);
  const html = res.buf.toString('utf8');
  const fixture = pucksFixture(html, slug);
  await writeFile(new URL(file, DIR), fixture, 'utf8');
  const price = /"price":"([^"]+)"/.exec(fixture)?.[1];
  const availability = /"availability":"([^"]+)"/.exec(fixture)?.[1];
  console.log('wrote', file, 'price', price, 'availability', availability);
}

