async function fetchJson(url) {
  const response = await fetch(url, { signal: AbortSignal.timeout(15_000) });
  if (!response.ok) throw new Error(`GET ${url} -> ${response.status}`);
  return response.json();
}

function fetchBoard(baseUrl, grams, dest, variant = 'classico', product = null) {
  const params = new URLSearchParams({ grams: String(grams), dest, variant });
  if (product) params.set('product', product);
  return fetchJson(`${baseUrl}/api/board?${params}`);
}

async function webdriver(method, path, body) {
  const response = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: body ? { 'content-type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000)
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(`${method} ${path} -> ${response.status} ${JSON.stringify(payload)}`);
  return payload;
}

/** W3C WebDriver returns the element key `element-6066-...`; legacy drivers use `ELEMENT`. */
function elementId(found) {
  const value = found?.value ?? {};
  const id = value['element-6066-11e4-a52e-4f735466cecf'] ?? value.ELEMENT;
  if (!id) throw new Error(`element not found: ${JSON.stringify(found).slice(0, 200)}`);
  return id;
}

async function evaluate(wd, script) {
  const expression = script.trim().startsWith('return') ? script : `return ${script}`;
  const result = await wd('POST', '/execute/sync', { script: expression, args: [] });
  return result.value;
}

async function waitFor(predicate, timeoutMs, label) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await predicate()) return true;
    await delay(250);
  }
  throw new Error(`timeout waiting for ${label}`);
}

/** Poll a page-side expression until it is truthy; report page state on timeout. */
async function waitForPage(wd, expression, timeoutMs, label, probe) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      if (await evaluate(wd, expression)) return true;
    } catch {
      // Transient evaluate failures (for example during a re-render) are retried.
    }
    await delay(250);
  }
  let detail = '';
  if (probe) {
    try {
      detail = `; page state: ${JSON.stringify(await evaluate(wd, probe))}`;
    } catch (error) {
      detail = `; page state unavailable: ${error?.message ?? error}`;
    }
  }
  throw new Error(`timeout waiting for ${label}${detail}`);
}

async function waitForBoard(wd) {
  await waitFor(async () => evaluate(wd, `document.body.dataset.boardState === 'ready' && !!document.querySelector('.best, .empty')`), 20_000, 'board render');
}

async function screenshot(wd, name) {
  const shot = await wd('GET', '/screenshot');
  await writeFile(`${OUT}/${name}`, Buffer.from(shot.value, 'base64'));
}

// The local cron simulation must be repeatable: it is the command the handoff
// notes and the agent loop use to prove the scheduled pipeline still works.
// A fixture run must never be silently skipped because a previous run left a
// six-hour backoff window behind, and it must never consume the live run's
// state file either.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const run = promisify(execFile);
const script = fileURLToPath(new URL('../scripts/simulate-cron.mjs', import.meta.url));

async function simulate(cwd) {
  const { stdout, stderr } = await run(process.execPath, [script, '--offline'], {
    cwd,
    env: { ...process.env, BOARD_STATE_PATH: '' },
    timeout: 60_000
  });
  return { report: JSON.parse(stdout), stderr };
}

test('cron:offline simulation runs the full fixture pipeline twice in a row', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'cron-simulation-'));
  try {
    const first = await simulate(dir);
    const second = await simulate(dir);

    for (const [label, { report }] of [['first', first], ['second', second]]) {
      assert.equal(report.mode, 'offline fixtures', `${label} run mode`);
      assert.equal(report.summary.requests, 15, `${label} run stays inside the request budget`);
      assert.deepEqual(
        report.summary.vendors.map(vendor => [vendor.vendorId, vendor.saved, vendor.skipped ?? false]),
        [['coffeeman', 8, false], ['pucks', 5, false], ['coffee4u', 1, false]],
        `${label} run refreshes every vendor`
      );
      assert.equal(report.offers.length, 14, `${label} run persists all fourteen tracked offers`);
      assert.ok(report.offers.every(offer => offer.observedAt === report.summary.startedAt), `${label} run observations are fresh`);
      assert.ok(report.fx?.usd?.rate > 0, `${label} run records an FX reference rate`);
    }

    // The fixture run keeps its own state file so it can never consume the live
    // run's backoff window, and the state really is persisted between runs.
    const state = JSON.parse(await readFile(join(dir, '.shurik-local', 'board-offline.json'), 'utf8'));
    assert.equal(state.observations.length, 14);
    assert.equal(Object.keys(state.vendors).length, 3);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

