  {
    id: 'lavazza-qualita-rossa-vacuum-ground',
    line: 'Qualità Rossa',
    patterns: [
      /qualit[aàáy]\s*rossa/i,
      /קוואליטה\s*רוסה/,
      /קווליטה\s*רוסה/,
      /לווצה\s*רוסה/
    ]
  },
  {
