// Build the post-deploy production evidence file from the raw captures (run once).
import { readFileSync, writeFileSync } from 'node:fs';

const read = name => JSON.parse(readFileSync(`.shurik-local/prod-post/${name}.json`, 'utf8'));
const summarizeBoard = board => ({
  generatedAt: board.generatedAt,
  productId: board.productId,
  variantId: board.variantId,
  targetGrams: board.targetGrams,
  destination: board.destination,
  best: board.best && { vendorId: board.best.vendor.id, totalIls: board.best.totalIls, ilsPerKg: board.best.ilsPerKg, key: board.best.key },
  ranked: (board.ranked ?? []).map(q => ({ vendorId: q.vendor.id, key: q.key, totalIls: q.totalIls, ilsPerKg: q.ilsPerKg, shippingCertainty: q.shipping?.certaintyLabel ?? null })),
  unrankable: (board.unrankable ?? []).map(q => ({ vendorId: q.vendor.id, key: q.key, reasons: q.reasons })),
  counts: board.counts,
  requestedRetiredProduct: board.requestedRetiredProduct,
  freshness: board.freshness
});

const evidence = {
  capturedAt: '2026-10-12T16:17:58Z to 2026-10-12T16:18:00Z',
  mode: 'read-only public GETs from the coding runner to the owner-reported production URL after the supervisor published the 3-61 commits; no Cloudflare credentials, admin API, deploy or remote resource change',
  url: 'https://attention-shoppers.igormaka.workers.dev',
  interpretation: [
    '/health now includes lastObservationAt, a field only the 3-61 code emits. A build containing the 3-61 changes is therefore serving in production, which independently verifies that the main-push Workers Builds path deployed the pushed commits from this runner.',
    'The Durable Object store persisted across the deploy: lastRefreshAt (15:52:12.546Z) and lastObservationAt (15:51:52.931Z) are the same values recorded by the 15:51-15:52 probe, and /api/status still reports the same five observations and the single completed initial run.',
    'Board values are unchanged and match the documented expectations: 500 g best NIS 91.00, 1 kg best NIS 149.00, unstated variant NIS 106.00, and the retired Qualita Oro URL falls back with requestedRetiredProduct and no retired offer in the payload.',
    'Freshness now exposes lastObservationAt and dataAsOf in both /api/status and /api/board; ageHours was 0.4 and stale false at capture time. No cf-cache-status header was present on the responses.',
    'The 6-hour cron trigger has still not been observed firing from the runner; the observed refresh was request-triggered.'
  ],
  health: read('health'),
  status: read('api_status'),
  catalogSummary: {
    products: read('api_catalog').products.map(p => p.id),
    vendorIds: read('api_catalog').vendors.map(v => v.id)
  },
  board500: summarizeBoard(read('api_board_grams_500_dest_tel-aviv')),
  board1000: summarizeBoard(read('api_board_grams_1000_dest_tel-aviv')),
  boardUnstated: summarizeBoard(read('api_board_variant_unspecified_grams_500_dest_tel-aviv')),
  retiredUrl: summarizeBoard(read('api_board_product_lavazza-qualita-oro-vacuum-ground_grams_500_dest_tel-aviv'))
};
writeFileSync('docs/evidence/production-verification-20261012T1618Z.json', `${JSON.stringify(evidence, null, 2)}\n`);
console.log('post-deploy evidence written');

