// Bounded read-only sitemap re-probe for new Lavazza Crema e Gusto ground listings
// at the three tracked vendors. One fetch per sitemap, 8 s timeout, 1.5 MB cap,
// no anti-bot bypass, results written as JSON evidence.
import { mkdir, writeFile } from 'node:fs/promises';

const UA = 'attention-shoppers-research/0.1 (contact: repo maintainer)';
const MAX_BYTES = 1_500_000;
const TIMEOUT_MS = 8000;

async function get(url) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort('timeout'), TIMEOUT_MS);
  try {
    const response = await fetch(url, { headers: { 'user-agent': UA, accept: 'application/xml,text/xml,*/*' }, signal: controller.signal });
    const buffer = await response.arrayBuffer();
    const text = new TextDecoder('utf-8').decode(buffer.slice(0, MAX_BYTES));
    return { status: response.status, bytes: buffer.byteLength, text };
  } catch (error) {
    return { status: 0, error: error?.name === 'AbortError' ? `timeout after ${TIMEOUT_MS}ms` : String(error?.message ?? error) };
  } finally {
    clearTimeout(timer);
  }
}

const roots = [
  'https://www.coffeeman.co.il/sitemap.xml',
  'https://pucks.co.il/sitemap.xml',
  'https://www.coffee4u.co.il/sitemap.xml'
];

const results = [];
for (const root of roots) {
  const response = await get(root);
  const urls = [...(response.text ?? '').matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map(match => match[1]);
  const children = urls.filter(url => url.endsWith('.xml'));
  const crema = urls.filter(url => /crema/i.test(url));
  const childResults = [];
  for (const child of children.slice(0, 20)) {
    const childResponse = await get(child);
    const childUrls = [...(childResponse.text ?? '').matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map(match => match[1]);
    childResults.push({
      url: child,
      status: childResponse.status,
      error: childResponse.error ?? null,
      count: childUrls.length,
      crema: childUrls.filter(url => /crema/i.test(url))
    });
  }
  results.push({
    root,
    status: response.status,
    error: response.error ?? null,
    bytes: response.bytes ?? null,
    childSitemaps: children,
    cremaOnRoot: crema,
    children: childResults
  });
}

const allCrema = results.flatMap(entry => [...entry.cremaOnRoot, ...entry.children.flatMap(child => child.crema)]);
const snapshot = {
  probedAt: new Date().toISOString(),
  note: 'Bounded read-only sitemap re-probe of the three tracked vendors; no anti-bot bypass, no adapter change. Looks only for additional Crema e Gusto listings (new pack sizes/multipacks).',
  results,
  cremaUrls: [...new Set(allCrema)]
};
await mkdir('.shurik-local/probes', { recursive: true });
const out = `.shurik-local/probes/sitemap-reprobe-${snapshot.probedAt.replace(/[:.]/g, '-')}.json`;
await writeFile(out, `${JSON.stringify(snapshot, null, 2)}\n`);
console.log(`Evidence: ${out}`);
for (const entry of results) {
  console.log(`${entry.root} -> HTTP ${entry.status}${entry.error ? ` (${entry.error})` : ''} children=${entry.childSitemaps.length} cremaUrls=${entry.children.reduce((sum, child) => sum + child.crema.length, entry.cremaOnRoot.length)}`);
}
for (const url of snapshot.cremaUrls) console.log(`  ${url}`);

