function packDescription(quote) {
  const p = quote.product ?? {};
  const per = p.packGrams != null ? `${p.packGrams} g` : '? g';
  if ((p.packCount ?? 1) > 1) return `${p.packCount} × ${per} multipack (${p.totalGrams} g)`;
  return `${per} pack`;
}
function quantityDescription(quote) {
  const units = quote.units ?? 1;
  const p = quote.product ?? {};
  const per = (p.packCount ?? 1) > 1 ? `${p.packCount} × ${p.packGrams} g multipack` : `${p.packGrams} g pack`;
  return `${units} × ${per} = ${quote.orderedGrams} g`;
}
function shippingText(quote) {
  if (quote.shipping?.amountIls != null) {
    if (quote.shipping.amountIls === 0) return quote.shipping.freeThreshold != null ? 'Free (threshold met)' : 'Free';
    return money(quote.shipping.amountIls);
  }
  if (quote.shipping?.amount != null) return `${money(quote.shipping.amount)} ${quote.shipping.currency ?? ''} (not converted)`;
  return 'Shipping not published';
}
function shippingServiceText(quote) {
  return quote.shipping?.mode === 'pickup' ? 'Pickup' : quote.shipping?.certaintyLabel ?? 'Not published before checkout';
}
