      includePerKg && quote.ilsPerKg != null ? el('span', { class: 'totals__meta num', text: `${money(quote.ilsPerKg)} per kg` }) : null));
}

/** One written conditions list per offer; the same caveat is never repeated on a card. */
function conditionsList(quote) {
  const shipping = quote.shipping ?? {};
