    coverageCaveat ? `${desktop.bestTerms.join(' | ')} :: ${desktop.bestValues.join(' | ')}` : 'no caveat in the API payload');
  const itemMathOk = api500.ranked.length >= 2 && api500.ranked.every((quote, index) => {
